def shell_sort(arr):
    def gap_insertion_sort(gap, arr):
        for i in range(gap, len(arr)):
            value = arr[i]
            j = i
            while j >= gap and arr[j - gap] > value:
                arr[j] = arr[j - gap]
                j -= gap
            arr[j] = value

    size = len(arr)
    interval = size // 2
    while interval > 0:
        for i in range(interval, size):
            gap_insertion_sort(interval, arr)
        interval //= 2

    return arr

