def lps(s):
    if not s:
        return 0

    dp = [[0] * len(s) for _ in range(len(s))]

    for i in range(len(s)):
        dp[i][i] = 1

    for cl in range(2, len(s) + 1):
        for i in range(len(s) - cl + 1):
            j = i + cl - 1
            if s[i] == s[j]:
                dp[i][j] = dp[i+1][j-1] + 2
            else:
                dp[i][j] = max(dp[i+1][j], dp[i][j-1])

    return dp[0][-1]

