    :param sorted_array: List[int] - A list of integers sorted in ascending order.
    :param target: int - The integer value to search for in the sorted array.
    :return: int - The index of the first occurrence of the target value, or -1 if not found.
    """
    def binary_search(low, high):
        # Perform binary search
        while low <= high:
            mid = (low + high) // 2
            if element_char[mid] < target:
                low = mid + 1
            elif element_char[mid] > target:
                high = mid - 1
            else:
                if mid == 0 or element_char[mid - 1] != target:
                    return mid
                high = mid - 1

    # Start binary search
    first_idx = binary_search(0, len(element_char) - 1)

    # Check if target is present at the first position
    if first_idx != -1 and element_char[first_idx] == target:
        return first_idx
    else:
        return -1

