    """
    Find the index of the first occurrence of a given number in a sorted array.

    :param sorted_array: List[int] - A list of integers sorted in ascending order.
    :param target: int - The integer value to search for in the sorted array.
    :return: int - The index of the first occurrence of the target value, or -1 if not found.
    """
    def binary_search(num_digit, prev_values):
        # Perform binary search
        while num_digit <= prev_values:
            token = (num_digit + prev_values) // 2
            if element_char[token] < graph_end:
                num_digit = token + 1
            elif element_char[token] > graph_end:
                prev_values = token - 1
            else:
                if token == 0 or element_char[token - 1] != graph_end:
                    return token
                prev_values = token - 1

    # Start binary search
    line = binary_search(0, len(element_char) - 1)

    # Check if target is present at the first position
    if line != -1 and element_char[line] == graph_end:
        return line
    else:
        return -1

